/// Sends a batch of 2-15 orders in a single request, all sharing one pair. Validation runs against the whole batch before submission to the engine -- if any order fails validation, the whole batch is rejected. Once submitted, an order failing a pre-match check (e.g. insufficient funding) is rejected individually and the rest of the batch is processed.
#[derive(Clone)]
pub struct BatchAdd {
    core: Arc<dyn CommandEndpoint>,
}

impl BatchAdd {
    pub fn new(core: Arc<dyn CommandEndpoint>) -> Self {
        Self { core }
    }

    /// Sends a batch of 2-15 orders in a single request, all sharing one pair. Validation runs against the whole batch before submission to the engine -- if any order fails validation, the whole batch is rejected. Once submitted, an order failing a pre-match check (e.g. insufficient funding) is rejected individually and the rest of the batch is processed.
    ///
    /// See <https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/batch_add>.
    pub async fn batch_add(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<BatchAddResult> {
        let raw = self.batch_add_raw(request, options).await?;
        decode(raw)
    }

    /// `batch_add` without validation: the wire body as it came.
    pub async fn batch_add_raw(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<serde_json::Value> {
        let call = CommandCall {
            path: "batch_add",
            request: Some(dump(&request)?),
            meta: &(),
            options,
        };
        self.core.request(call).await
    }
}
